  'This course studies retailing as a strategic, analytical, operational, and customer-experience discipline. Students learn how retailers create value through formats, location, store and digital experience, merchandise planning, buying, category management, pricing, omnichannel execution, technology, analytics, fulfillment, service, loyalty, retail media, and responsible retailing. The course culminates in a practical retail strategy plan supported by customer insight, financial metrics, operational logic, and ethical judgment.',
  $retljson${"slug": "retailing", "title": "Retailing", "description": "This course studies retailing as a strategic, analytical, operational, and customer-experience discipline. Students learn how retailers create value through formats, location, store and digital experience, merchandise planning, buying, category management, pricing, omnichannel execution, technology, analytics, fulfillment, service, loyalty, retail media, and responsible retailing. The course culminates in a practical retail strategy plan supported by customer insight, financial metrics, operational logic, and ethical judgment.", "topics": [{"id": "323e545f-654b-4202-8194-8529b2c60ced", "type": "topic", "title": "Retail Strategy and the Retail Business Model", "description": "Students begin by seeing retail as a business model: value proposition, target customer, assortment, format, location or platform, margin structure, and operating system.", "children": [{"id": "685709f5-d1a7-4471-a14b-803055fc02eb", "type": "subtopic", "title": "Retail value creation", "children": [{"id": "fcf53c8d-a32b-4006-89c8-f8e8647db3db", "type": "concept", "title": "Customer problem and shopping mission"}, {"id": "99f5156d-a9be-4f9e-8968-4b24447ffa66", "type": "concept", "title": "Convenience, selection, price, experience, and service"}, {"id": "0753fb11-4e4c-4d03-a757-e00bdff74302", "type": "concept", "title": "Retail profit model and strategic tradeoffs"}], "description": "The point is to understand how retailers create value for customers and suppliers while earning sustainable margins."}, {"id": "347e1e8a-439c-4bf1-83cd-0fdbd00b8c48", "type": "subtopic", "title": "Retail strategy frameworks", "children": [{"id": "5c524ffb-65cc-4318-b058-a71af5d3d2ae", "type": "concept", "title": "Target market and positioning"}, {"id": "d0a1bc71-36a5-4442-8fef-70da6f7fedd3", "type": "concept", "title": "Retail mix: assortment, price, place, promotion, people, process, physical/digital evidence"}, {"id": "c86e3d2b-767c-490a-96df-6b886c1bdde8", "type": "concept", "title": "Differentiation versus cost leadership"}], "description": "Students learn to connect STP, competitive positioning, and the retail mix."}, {"id": "091335c6-ab94-493a-9aef-7220cc98b9f3", "type": "subtopic", "title": "Retail economics", "children": [{"id": "0ea8a05f-e45e-4ff5-8fcc-9bc18e4ea45a", "type": "concept", "title": "Same-store sales and traffic"}, {"id": "533b9dbe-2176-42d8-a27c-0ef3b4ff40a6", "type": "concept", "title": "Gross margin return on investment"}, {"id": "0dcd8a2d-a354-4cad-b985-95bff5acbce3", "type": "concept", "title": "Contribution margin and break-even logic"}], "description": "The gist is to connect strategy to sales productivity, gross margin, inventory turns, markdowns, and operating leverage."}]}, {"id": "3829e958-2094-403e-9f89-3ba2edf2f5e8", "type": "topic", "title": "Retail Formats, Institutions, and Competitive Landscapes", "description": "This topic maps the major retail formats and the competitive pressures reshaping each one.", "children": [{"id": "72449c77-b5bf-47b9-84f7-a03af0a99769", "type": "subtopic", "title": "Store-based formats", "children": [{"id": "d94adde4-bca7-453d-b2d6-64a77400a318", "type": "concept", "title": "Department, specialty, discount, mass, convenience, supermarket, warehouse club"}, {"id": "fe200c00-a687-426e-b0f8-d52be98204c5", "type": "concept", "title": "Luxury, off-price, pop-up, and experiential stores"}, {"id": "e8f6cdc6-59da-48a5-94b1-771d9aed7ed8", "type": "concept", "title": "Franchise and chain formats"}], "description": "Students learn how format shapes assortment, service level, cost structure, and customer expectations."}, {"id": "ae15a54d-6b73-45a0-b862-a04978814e8a", "type": "subtopic", "title": "Digital and hybrid formats", "children": [{"id": "b0ddff59-60a6-48a9-a2ba-49e1f1aedf96", "type": "concept", "title": "Pure-play ecommerce and marketplaces"}, {"id": "ff76dd85-a131-4476-b271-c33b740af777", "type": "concept", "title": "Direct-to-consumer and subscription retail"}, {"id": "6a7a634d-102b-4f24-b98f-9093bfe5ff65", "type": "concept", "title": "Social commerce and live shopping"}], "description": "The point is to compare ecommerce, marketplaces, social commerce, DTC, subscriptions, and omnichannel models."}, {"id": "3ce2ae11-ac97-46f1-aaa3-c6747111a915", "type": "subtopic", "title": "Competitive analysis", "children": [{"id": "a63104f7-86f5-4738-9e95-a9f84570072f", "type": "concept", "title": "Share of wallet and competitive set"}, {"id": "dbddcd2b-a625-4e23-8773-a7a671127998", "type": "concept", "title": "Category killers and platform competition"}, {"id": "2ee5e4db-9c4c-4f1e-ab36-e636ae3ec7be", "type": "concept", "title": "Private label and vertical integration"}], "description": "Students evaluate retail rivalry using formats, customer segments, channel economics, and category dynamics."}]}, {"id": "ae91e35d-d258-4626-a2a6-1c7cb0baec5d", "type": "topic", "title": "Retail Location, Trade Area, and Site Strategy", "description": "Location remains strategic even in digital retail because customer access, fulfillment, visibility, and local demand still matter.", "children": [{"id": "c94c5591-64bb-4cde-8c06-ee6268cd8983", "type": "subtopic", "title": "Trade area analysis", "children": [{"id": "f56834d2-5cb1-4a92-9f68-826311724a4b", "type": "concept", "title": "Primary, secondary, and tertiary trade areas"}, {"id": "f2f2e010-2b81-42d9-b549-0487f7760190", "type": "concept", "title": "Demographics, psychographics, and mobility patterns"}, {"id": "c76d9743-86df-40d2-a27d-a0d2a6993442", "type": "concept", "title": "Cannibalization and white-space analysis"}], "description": "Students learn to evaluate the geographic market a store or service node can realistically serve."}, {"id": "457c2b7e-696e-42e8-a00f-17b48789716e", "type": "subtopic", "title": "Site selection", "children": [{"id": "2e9d31b6-b561-460f-99c6-89a38487d925", "type": "concept", "title": "Mall, high street, lifestyle center, strip, standalone, and urban formats"}, {"id": "55dc4e84-877e-41c0-8fc5-7d02797a7f06", "type": "concept", "title": "Foot traffic and conversion potential"}, {"id": "6af37678-62df-4290-bfed-9f53588e7565", "type": "concept", "title": "Lease terms and occupancy cost"}], "description": "The gist is to balance traffic, access, rent, co-tenancy, visibility, and operational feasibility."}, {"id": "5b27ae55-43d6-4914-b0dd-f2fc2c6e1329", "type": "subtopic", "title": "Location analytics", "children": [{"id": "f0fc8aeb-bef8-4d82-9454-9d57247fec6e", "type": "concept", "title": "GIS and heat maps"}, {"id": "eb06429c-f526-441a-bf59-1b9af0be1cdd", "type": "concept", "title": "Catchment modeling"}, {"id": "73795fca-08b2-486f-ad69-7e47554ec999", "type": "concept", "title": "Store network optimization"}], "description": "Students examine how geospatial data, mobile data, and sales data support location decisions."}]}, {"id": "a541ae2a-5655-4ffb-8957-9775edec1814", "type": "topic", "title": "Store Layout, Visual Merchandising, and Atmospherics", "description": "Students study how physical environments guide attention, movement, emotion, discovery, and purchase behavior.", "children": [{"id": "08e080eb-1236-4b1a-9d92-9e5bda5c30e4", "type": "subtopic", "title": "Layout and shopper flow", "children": [{"id": "0c8e413f-7201-47bb-b7ae-5123c47d7ac7", "type": "concept", "title": "Grid, racetrack, free-flow, and boutique layouts"}, {"id": "9acf0e24-449f-492f-86d8-50259b209e56", "type": "concept", "title": "Adjacency, sightlines, and decompression zones"}, {"id": "591957c0-b5bf-41b8-a668-ceb60205eb48", "type": "concept", "title": "Checkout, queue, and service zones"}], "description": "Students learn how store layout manages navigation, exposure, dwell time, and operational efficiency."}, {"id": "412259d5-6fbe-47b4-b901-98ada063fd64", "type": "subtopic", "title": "Visual merchandising", "children": [{"id": "a9b85bae-f791-401d-96e6-dde167067c6a", "type": "concept", "title": "Planograms and fixture strategy"}, {"id": "0c3e2ee1-88fa-4b44-9c8b-e9160b96966c", "type": "concept", "title": "Endcaps, displays, signage, and storytelling"}, {"id": "0f407b87-f84c-4da8-b2af-522241ee018f", "type": "concept", "title": "Seasonal and promotional presentation"}], "description": "The point is to turn assortment strategy into a readable, persuasive shopping environment."}, {"id": "f4d33493-3236-4f66-8ff7-22935c22c21a", "type": "subtopic", "title": "Atmospherics and experience design", "children": [{"id": "dff6c102-a2ba-428a-97f0-8fc3429b1030", "type": "concept", "title": "Lighting, music, scent, texture, and color"}, {"id": "75028df4-d4b6-44ea-a5d7-344061b77cd5", "type": "concept", "title": "Comfort, accessibility, and wayfinding"}, {"id": "e174f78c-4109-413c-9db0-1add39f86b74", "type": "concept", "title": "Experience measurement and experimentation"}], "description": "Students connect sensory cues to brand meaning and customer behavior."}]}, {"id": "35763a52-8640-4e78-b57e-a9f8053605ca", "type": "topic", "title": "Shopper Behavior and Customer Decision Journeys", "description": "Retailing requires a practical understanding of how shoppers plan, search, compare, buy, return, and form habits.", "children": [{"id": "8cf18685-1576-4ada-b648-a7d8cdb38cc6", "type": "subtopic", "title": "Shopper missions and occasions", "children": [{"id": "3c78e2e1-fdde-4c8f-bc25-7af7da2e21fb", "type": "concept", "title": "Stock-up, fill-in, emergency, discovery, gifting, and browsing missions"}, {"id": "983cd9f0-b8f6-4cdf-ac4d-e86adb52cc19", "type": "concept", "title": "Trip types and basket composition"}, {"id": "fc237507-b768-43db-918f-e15300b43074", "type": "concept", "title": "Need states and occasion-based merchandising"}], "description": "Students segment behavior by why the shopper is buying now, not only who the customer is."}, {"id": "7fc697ca-17a0-4088-9d7b-d2f15bb04526", "type": "subtopic", "title": "Behavioral science in retail", "children": [{"id": "aaf6b3a2-94a4-4471-bc37-141ed70d9fcb", "type": "concept", "title": "Choice architecture"}, {"id": "13e5e487-c82d-451f-8921-48072cbf4c5a", "type": "concept", "title": "Anchoring, framing, and reference prices"}, {"id": "9c4a36c9-0d60-4d49-9c67-8de15de9281c", "type": "concept", "title": "Impulse, habit, and loyalty"}], "description": "The gist is to use attention, friction, defaults, social proof, scarcity, and price perception responsibly."}, {"id": "e03e094a-353a-4823-9628-7148ca08e889", "type": "subtopic", "title": "Post-purchase behavior", "children": [{"id": "b45924a2-53d1-43b7-95f6-07d40937334f", "type": "concept", "title": "Returns and reverse logistics"}, {"id": "0fd884f3-36b4-4e31-87bd-c8f90c8ce87d", "type": "concept", "title": "Ratings, reviews, and word of mouth"}, {"id": "f1039891-d8fa-4b60-a2a7-3bd602518a97", "type": "concept", "title": "Retention, churn, and win-back"}], "description": "Students connect returns, service recovery, reviews, and CRM to lifetime value."}]}, {"id": "3171f12d-de13-427f-9034-3c3418ec1d58", "type": "topic", "title": "Merchandise Planning, Assortment, and Category Management", "description": "This unit explains how retailers decide what to sell, how much to buy, how to allocate it, and how categories perform together.", "children": [{"id": "6ffef05a-01cd-48a9-b942-e142f181e5ad", "type": "subtopic", "title": "Assortment strategy", "children": [{"id": "33f60c8f-d16e-4a32-a396-ec268cb72a8b", "type": "concept", "title": "Core, seasonal, and trend assortments"}, {"id": "56a97e0e-4b46-4559-b41d-5da373cdcda2", "type": "concept", "title": "Good-better-best architecture"}, {"id": "bc0012c4-53f9-40d7-ba5c-bcbb67dccfe8", "type": "concept", "title": "Localization and clustering"}], "description": "Students learn to design breadth, depth, brands, private label, price tiers, and local variation."}, {"id": "f8feda35-8546-497f-b4fc-7a34d9d6c5ca", "type": "subtopic", "title": "Merchandise financial planning", "children": [{"id": "55c0f02d-b5d3-48eb-98e4-e90ce8e3b1ec", "type": "concept", "title": "Sales forecasting and inventory budgets"}, {"id": "dc8cfd14-a3de-4ce1-b8e8-98c2ef218a53", "type": "concept", "title": "Open-to-buy planning"}, {"id": "b9944c9a-3e2f-41be-8e0a-6d8cde002349", "type": "concept", "title": "Sell-through and weeks of supply"}], "description": "The point is to link buying decisions to sales, margin, inventory turns, open-to-buy, and markdown risk."}, {"id": "dc09bb13-3769-4b40-b8c4-9072bd532100", "type": "subtopic", "title": "Category management", "children": [{"id": "10869826-9eef-40f6-8f1d-02b524c41fd6", "type": "concept", "title": "Category roles and scorecards"}, {"id": "452719ab-24f3-49d8-88c5-bb0c814188c6", "type": "concept", "title": "Planograms and space allocation"}, {"id": "4170a5ea-b1e9-438a-a21a-045f29a5868c", "type": "concept", "title": "Supplier collaboration and trade funds"}], "description": "Students learn how retailer and supplier goals meet at category roles, shelf space, promotions, and shopper insight."}]}, {"id": "e1dc30e7-6c53-4f46-b8c7-407a4a04134d", "type": "topic", "title": "Buying, Vendor Relations, and Private Label", "description": "Retail buyers shape customer choice while managing suppliers, negotiations, ethics, and risk.", "children": [{"id": "72c97d69-20b4-43ae-a243-1a5e991662a0", "type": "subtopic", "title": "Buying process", "children": [{"id": "d95290af-b3f2-4f7b-87ba-a388f590b588", "type": "concept", "title": "Line reviews and market weeks"}, {"id": "37f392be-9b7f-4baa-a652-a6251204b059", "type": "concept", "title": "Vendor scorecards"}, {"id": "a25216db-ccb7-4e35-90f9-cf89cb811cc6", "type": "concept", "title": "Terms, allowances, and service levels"}], "description": "Students learn how merchants identify needs, source products, evaluate vendors, negotiate terms, and manage performance."}, {"id": "c87e3751-fb78-4a97-88e9-95e9bacfacc2", "type": "subtopic", "title": "Private label and exclusive brands", "children": [{"id": "b7891395-aa1b-44fb-bd18-83d2c83b40fa", "type": "concept", "title": "National brand versus private label roles"}, {"id": "7bca7580-dc2c-40b0-a3d7-9ce2808d168d", "type": "concept", "title": "Product development and quality assurance"}, {"id": "63e2ec25-e2f4-446c-aabd-344b7d4dcf67", "type": "concept", "title": "Brand architecture and packaging"}], "description": "The gist is to examine how retailers build margin, differentiation, loyalty, and control through owned brands."}, {"id": "87fc1912-655a-40e5-b3f9-68093cba4a25", "type": "subtopic", "title": "Ethical sourcing and vendor governance", "children": [{"id": "4121e32a-7fa7-4a4c-8b6a-d80d7a7b62c5", "type": "concept", "title": "Supplier codes of conduct"}, {"id": "c61e7c25-54f4-4f69-9d88-b2a521947c5d", "type": "concept", "title": "Audits and traceability"}, {"id": "8c5afa56-ac2a-480f-8976-d76cfe6f3db4", "type": "concept", "title": "Conflict of interest and buying ethics"}], "description": "Students connect buying decisions to labor, safety, sustainability, compliance, and reputational risk."}]}, {"id": "48a1eec8-ca5e-4685-8b41-04102a168adf", "type": "topic", "title": "Retail Pricing, Promotion, and Revenue Management", "description": "Pricing in retail is fast, visible, competitive, and psychologically loaded; students learn to manage price as strategy, not arithmetic.", "children": [{"id": "d1144ce4-b4da-43fe-85a6-a94c7fd8a357", "type": "subtopic", "title": "Retail price architecture", "children": [{"id": "eec9ccd0-a85b-43cc-b7f1-f172176dbe6f", "type": "concept", "title": "Reference prices and price image"}, {"id": "a2f61350-ccd1-44b1-bca0-91c27d9445a5", "type": "concept", "title": "Competitive price zones"}, {"id": "1ab5429f-7ab6-446b-8935-84f7a1e4bdcc", "type": "concept", "title": "Margin, elasticity, and willingness to pay"}], "description": "Students understand everyday pricing, high-low pricing, EDLP, premium pricing, and price ladders."}, {"id": "d1a88791-bcee-4279-b2d5-90425e9af4cc", "type": "subtopic", "title": "Promotions and markdowns", "children": [{"id": "6a67242a-5340-442a-b1f2-927585710011", "type": "concept", "title": "Feature, display, coupon, loyalty, and bundle promotions"}, {"id": "2100fcb8-3f58-47e1-9c9f-91fc3bd17042", "type": "concept", "title": "Markdown cadence and clearance"}, {"id": "0155a024-7f03-40b5-8160-95767f296a4e", "type": "concept", "title": "Promotion lift and cannibalization"}], "description": "The point is to use promotions to create profitable demand rather than train customers to wait."}, {"id": "63eb3e65-da67-4002-8c3e-8d1a3b9e70dd", "type": "subtopic", "title": "Dynamic and personalized pricing", "children": [{"id": "56e17cdf-6a5c-4dbf-9268-43cb56e7972f", "type": "concept", "title": "Real-time price optimization"}, {"id": "d4d8d1a2-5af1-4f12-8d7a-0fe2fd3cfa27", "type": "concept", "title": "Price discrimination and transparency"}, {"id": "986d04f1-23f5-4eb6-b3c9-5898cb9c8546", "type": "concept", "title": "Legal and ethical constraints"}], "description": "Students consider algorithmic pricing opportunities and fairness risks."}]}, {"id": "28e62933-115f-455f-af65-7e82c6183c3f", "type": "topic", "title": "Omnichannel Retailing and Unified Commerce", "description": "This topic integrates stores, ecommerce, mobile, social, marketplaces, service, inventory, fulfillment, and data into one customer system.", "children": [{"id": "74d9f758-2a34-4410-afc0-a7a24db96820", "type": "subtopic", "title": "Omnichannel customer journeys", "children": [{"id": "d0c6e699-f433-4c78-a530-43550988bf59", "type": "concept", "title": "Research online, buy offline"}, {"id": "42d76e6a-9804-4369-a5e1-9e9d7245a938", "type": "concept", "title": "Buy online, pick up in store"}, {"id": "61ed6be5-2401-481f-9541-1bb7c86a669a", "type": "concept", "title": "Endless aisle and clienteling"}], "description": "Students map how customers move across touchpoints before, during, and after purchase."}, {"id": "b4ace957-ad6a-430e-8100-63fc70b3a5d8", "type": "subtopic", "title": "Unified inventory and fulfillment", "children": [{"id": "b74fdbd0-3047-46e7-a59f-82510f6072fb", "type": "concept", "title": "Ship-from-store and curbside pickup"}, {"id": "455b2842-3669-411e-a845-0afb7add6cc9", "type": "concept", "title": "Inventory visibility and allocation"}, {"id": "58f944c3-8eae-430c-a937-37cafbf15eab", "type": "concept", "title": "Returns across channels"}], "description": "The gist is to understand why omnichannel promises require operational integration."}, {"id": "02af8899-d472-4d4e-978b-69f68b2dae11", "type": "subtopic", "title": "Organizational integration", "children": [{"id": "ca0575a3-d7f2-43da-ae94-bedddeaf9e3a", "type": "concept", "title": "Channel conflict and attribution"}, {"id": "abd2030b-a953-4372-a8c1-ab2b69d6e3cc", "type": "concept", "title": "Shared KPIs and customer ownership"}, {"id": "662b6179-97d5-4555-98e8-62ae78489828", "type": "concept", "title": "Technology stack integration"}], "description": "Students learn how incentives, systems, and teams can either support or sabotage omnichannel execution."}]}, {"id": "69c901f7-caa0-4c38-95bb-d4e125803a32", "type": "topic", "title": "Retail Technology, Analytics, and AI", "description": "Modern retail runs on data: POS, loyalty, ecommerce, inventory, media, computer vision, forecasting, and AI-supported decisions.", "children": [{"id": "38a963ba-999e-42b0-9b87-a6ac89c3dabe", "type": "subtopic", "title": "Retail data foundations", "children": [{"id": "470ea9e3-2a40-481c-91d9-6000e22d2171", "type": "concept", "title": "POS, basket, loyalty, traffic, inventory, and clickstream data"}, {"id": "969d2b3a-c950-411f-9b67-a51592b982c3", "type": "concept", "title": "Customer identity resolution"}, {"id": "432a4151-3519-43df-a9f6-b182ceff3d4e", "type": "concept", "title": "Data privacy and governance"}], "description": "Students learn what data retailers collect and how it can improve decisions."}, {"id": "6dfc876a-dff0-454b-808a-0a99a7c1c300", "type": "subtopic", "title": "Analytics for retail decisions", "children": [{"id": "fc8f8c65-198e-42d3-b844-028a75729a09", "type": "concept", "title": "Demand forecasting"}, {"id": "0471b708-026a-43b6-88f6-1debc876405a", "type": "concept", "title": "Market basket analysis"}, {"id": "e17f4bc2-a827-4027-93a7-5c9f247916a7", "type": "concept", "title": "A/B testing and incrementality"}], "description": "The point is to apply analytics to forecasting, assortment, price, promotion, churn, and personalization."}, {"id": "8ad76319-0418-4a60-9e84-023fe22a8f4f", "type": "subtopic", "title": "AI and automation", "children": [{"id": "002c1f16-cb44-4ce8-a554-86981bd63ffc", "type": "concept", "title": "Recommendation systems"}, {"id": "a4e31dbf-3e6e-4b7f-a3f8-4c2b6f9e7c29", "type": "concept", "title": "Computer vision and smart shelves"}, {"id": "8bc7a5b6-a7f5-4b20-a9ef-96f722f22ea0", "type": "concept", "title": "Generative AI for service, content, and merchandising"}], "description": "Students evaluate emerging tools without losing sight of bias, privacy, accountability, and operational reality."}]}, {"id": "5c2ec205-19e3-4d6e-9611-ebb0ff4daca4", "type": "topic", "title": "Retail Supply Chain, Fulfillment, and Operations", "description": "Retail strategy must be executable: inventory, labor, fulfillment, store operations, and service levels determine the customer promise.", "children": [{"id": "6e27caae-02db-4049-93fa-17bf4674be14", "type": "subtopic", "title": "Inventory and replenishment", "children": [{"id": "14e37c90-511e-45f4-9ebe-1fa9568ca44e", "type": "concept", "title": "Safety stock and reorder points"}, {"id": "0e56f97c-f3b5-4910-a749-f42cddb0c92d", "type": "concept", "title": "Allocation and replenishment"}, {"id": "bbac72ff-8d7e-4b0e-99fc-df3200d7945d", "type": "concept", "title": "Out-of-stocks and overstock"}], "description": "Students learn the tradeoffs between availability, carrying cost, shrink, obsolescence, and service level."}, {"id": "d20b20a6-3bd3-4238-b321-ff8bba1b1504", "type": "subtopic", "title": "Fulfillment operations", "children": [{"id": "3477221f-5f0f-4c40-8827-409fe3d05124", "type": "concept", "title": "Pick, pack, ship, and delivery models"}, {"id": "54d9f7fa-51ce-47af-9248-5dd6c6025bb7", "type": "concept", "title": "Returns processing"}, {"id": "eb3be02a-cb96-4932-8ff5-69c651457362", "type": "concept", "title": "Cost-to-serve by channel"}], "description": "The gist is to compare distribution centers, stores, micro-fulfillment, dropship, third-party logistics, and last mile."}, {"id": "b9e85d76-7da5-4613-adf7-537d13afbaa0", "type": "subtopic", "title": "Store and labor operations", "children": [{"id": "811ba4dd-2b67-49c4-b502-417fbbbf087f", "type": "concept", "title": "Labor forecasting"}, {"id": "80cb8363-bce2-4b5f-b2f0-93d9273f8e03", "type": "concept", "title": "Shrink prevention and asset protection"}, {"id": "dd5adaeb-8ea8-4018-807e-e9510678ddc0", "type": "concept", "title": "Standard operating procedures"}], "description": "Students connect labor scheduling, training, task management, shrink, and service standards to retail performance."}]}, {"id": "621be2f3-5160-4185-8bc3-17382e9c955c", "type": "topic", "title": "Customer Experience, Service, Loyalty, and CRM", "description": "Retail winners design experiences that are useful, memorable, trustworthy, and measurable.", "children": [{"id": "bb83ecc6-a7cf-4975-bd6b-b2c0c56ef933", "type": "subtopic", "title": "Customer experience design", "children": [{"id": "f2523c14-ec5b-442b-b764-1d8bd711c772", "type": "concept", "title": "Journey mapping and pain points"}, {"id": "e841e443-cea8-4418-beef-4e91f7806817", "type": "concept", "title": "Service blueprints"}, {"id": "286d1586-cc08-44f7-a5ff-f29ddffcbdc8", "type": "concept", "title": "Moments of truth and friction removal"}], "description": "Students learn how to design and measure the full retail experience."}, {"id": "1496e570-1bc1-45f6-b2db-40d91d387a2f", "type": "subtopic", "title": "Service quality and frontline execution", "children": [{"id": "16714329-5d13-44b1-8727-6687611ac9e7", "type": "concept", "title": "Hiring and training"}, {"id": "62772dc3-0494-4fc2-a35f-1f4e6a35e912", "type": "concept", "title": "Service recovery"}, {"id": "daea6419-9001-4813-a2b7-589c2620f1c5", "type": "concept", "title": "Mystery shopping and quality monitoring"}], "description": "The point is to connect brand promise to associate behavior, scripts, empowerment, and recovery."}, {"id": "2bef1a51-eb53-4170-9e15-a0906836311b", "type": "subtopic", "title": "Loyalty and CRM", "children": [{"id": "a5cc546e-b690-47a0-ad4b-a188ee93ce4b", "type": "concept", "title": "Points, tiers, perks, subscriptions, and memberships"}, {"id": "67347d33-6341-4454-9a49-2e6405d187ff", "type": "concept", "title": "Personalization and lifecycle marketing"}, {"id": "bfee0343-8eb1-4217-b25c-80299ff345ae", "type": "concept", "title": "CLV, churn, and retention metrics"}], "description": "Students evaluate loyalty programs as data systems, value exchanges, and behavior-change tools."}]}, {"id": "c4ee12af-14b7-47ba-a7f7-81d7aa0aaec2", "type": "topic", "title": "Retail Media, Digital Marketing, and Marketplace Growth", "description": "Retailers increasingly act as media platforms, and brands increasingly depend on retail media, search, content, reviews, and marketplace algorithms.", "children": [{"id": "95bddb57-e7f2-40f4-8069-d59d886489a2", "type": "subtopic", "title": "Retail media networks", "children": [{"id": "9613466b-43bd-4b9c-b89e-eb041761bd45", "type": "concept", "title": "Sponsored search and display"}, {"id": "a4b0545f-6444-487f-ab45-0869fb447026", "type": "concept", "title": "Closed-loop measurement"}, {"id": "ffcf82b9-9d96-4123-8382-a268ee3cf0ac", "type": "concept", "title": "Supplier funding and media governance"}], "description": "Students learn why retailer first-party data has become strategically valuable."}, {"id": "8fdcd4e5-5d1f-4c4b-9ddb-ec8e2ffe3719", "type": "subtopic", "title": "Marketplace and ecommerce merchandising", "children": [{"id": "374a5dad-0b8b-4f42-ba04-bb433b10032e", "type": "concept", "title": "Product detail pages and content quality"}, {"id": "c4a4bcbd-5431-4189-a610-f812a57ff551", "type": "concept", "title": "Ratings, reviews, and Q&A"}, {"id": "262b7342-89da-471e-b266-f76951f84c0f", "type": "concept", "title": "Search rank, availability, and buy box logic"}], "description": "The gist is to manage digital shelf performance and conversion."}, {"id": "24a12816-4e4e-4b44-aa00-3e2277f5dc24", "type": "subtopic", "title": "Digital growth tactics", "children": [{"id": "e8c80360-768f-4889-9ef9-d7bdf28efcfd", "type": "concept", "title": "SEO/SEM and local search"}, {"id": "eef32d74-5725-414f-bc4e-c8e6890eb108", "type": "concept", "title": "Email, SMS, app, and push marketing"}, {"id": "6b42b134-05b3-495e-8ea0-f0be7bd1ee6c", "type": "concept", "title": "Influencers, affiliates, and social commerce"}], "description": "Students connect paid, owned, earned, CRM, and creator tactics to retail economics."}]}, {"id": "291065a9-ebfa-4c11-904f-f4e6ad1d3271", "type": "topic", "title": "Responsible Retailing, Sustainability, and Inclusion", "description": "World-class retail education must address labor, accessibility, environmental impact, privacy, community effects, and consumer welfare.", "children": [{"id": "3c265e35-1c81-4e6c-aebd-1ed9eead3d4d", "type": "subtopic", "title": "Sustainable retail", "children": [{"id": "c7546486-87fd-4d8b-94fc-45c80f6a4d6b", "type": "concept", "title": "Circular retail and resale"}, {"id": "b92aa949-306a-4a66-b921-bfdb35f8a1d9", "type": "concept", "title": "Waste reduction and reverse logistics"}, {"id": "da46967c-3099-4400-bce6-df08317e214b", "type": "concept", "title": "Greenwashing risk"}], "description": "Students examine packaging, logistics, waste, circularity, returns, energy, and credible environmental claims."}, {"id": "b186e15b-5e90-44d2-949a-d9c9a6d5c486", "type": "subtopic", "title": "Inclusive and accessible retail", "children": [{"id": "b0625951-99ae-4ef5-a576-3c27b3e91d1a", "type": "concept", "title": "ADA and accessible store/digital design"}, {"id": "5b353747-cc4e-42db-bdc2-aaa658771a46", "type": "concept", "title": "Inclusive sizing, language, and representation"}, {"id": "5c66f667-163e-4d8a-b655-6d2485c85967", "type": "concept", "title": "Food deserts, financial access, and community impact"}], "description": "The point is to design retail systems that serve more customers fairly."}, {"id": "d6a02408-41fa-4a82-b535-4291aba8d8d9", "type": "subtopic", "title": "Privacy, trust, and responsible influence", "children": [{"id": "88937ce8-54ad-48fe-86bf-8aca699d0d08", "type": "concept", "title": "Data privacy and loyalty programs"}, {"id": "99542381-27ed-465a-b8fe-a02ca3ebf56a", "type": "concept", "title": "Dark patterns and manipulative design"}, {"id": "38853dfc-ca44-4015-ba6e-f9cd4ccafb8a", "type": "concept", "title": "Responsible promotions and vulnerable consumers"}], "description": "Students weigh personalization and persuasion against consent, transparency, fairness, and consumer autonomy."}]}, {"id": "a98fbffb-ed90-4c23-959a-dc9c871195ca", "type": "topic", "title": "Retail Strategy Capstone and Performance Management", "description": "The course closes by integrating strategy, customer insight, merchandise, operations, technology, finance, and ethics into a defensible retail plan.", "children": [{"id": "836b1b10-8ed5-467c-ac4e-36cdd1cd23c5", "type": "subtopic", "title": "Retail scorecards", "children": [{"id": "f92ac7bb-790d-494c-8ec4-a59096cb226d", "type": "concept", "title": "Traffic, conversion, AOV, UPT, sales per square foot, GMROI"}, {"id": "f8f82da6-222b-416d-834c-11418e06bfe3", "type": "concept", "title": "CAC, CLV, retention, NPS, fulfillment cost"}, {"id": "f933e4d7-5864-4aae-9a62-afeeb5890f98", "type": "concept", "title": "Service level, shrink, and inventory productivity"}], "description": "Students learn to choose metrics that match the retail model and strategic objective."}, {"id": "d642d173-1d82-43b2-af57-7af590edeb23", "type": "subtopic", "title": "Experimentation and improvement", "children": [{"id": "e770be9a-7f34-4007-acc6-884156b7a2c7", "type": "concept", "title": "Store pilots"}, {"id": "8012b929-47b7-440e-bf91-987f40f89c24", "type": "concept", "title": "A/B tests and incrementality"}, {"id": "a20602b2-dc7e-41c8-bad3-a59bddbb16a0", "type": "concept", "title": "Rollout decisions and learning agendas"}], "description": "The point is to build a test-and-learn operating rhythm."}, {"id": "b6846861-74ed-43a1-9324-4c94c46c6fb6", "type": "subtopic", "title": "Capstone retail plan", "children": [{"id": "d2392492-b431-494a-92fb-1660c309e0e2", "type": "concept", "title": "Format and positioning"}, {"id": "8e40f0e8-98ff-4dbe-8e75-a531c8a9339e", "type": "concept", "title": "Assortment, price, channel, experience, and operations"}, {"id": "d14f2b1f-6834-4c2d-acc0-786f1d239cde", "type": "concept", "title": "Financial model, risks, and implementation roadmap"}], "description": "Students synthesize the course into a practical, investor- or executive-ready recommendation."}]}], "dbBacked": true}$retljson$::jsonb,
