  ('6ffef05a-01cd-48a9-b942-e142f181e5ad', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', '3171f12d-de13-427f-9034-3c3418ec1d58', 'subtopic'::public.curated_course_node_type, 'Assortment strategy', 'Students learn to design breadth, depth, brands, private label, price tiers, and local variation.', 0),
  ('33f60c8f-d16e-4a32-a396-ec268cb72a8b', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', '6ffef05a-01cd-48a9-b942-e142f181e5ad', 'concept'::public.curated_course_node_type, 'Core, seasonal, and trend assortments', null, 0),
  ('56a97e0e-4b46-4559-b41d-5da373cdcda2', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', '6ffef05a-01cd-48a9-b942-e142f181e5ad', 'concept'::public.curated_course_node_type, 'Good-better-best architecture', null, 1),
  ('bc0012c4-53f9-40d7-ba5c-bcbb67dccfe8', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', '6ffef05a-01cd-48a9-b942-e142f181e5ad', 'concept'::public.curated_course_node_type, 'Localization and clustering', null, 2),
  ('f8feda35-8546-497f-b4fc-7a34d9d6c5ca', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', '3171f12d-de13-427f-9034-3c3418ec1d58', 'subtopic'::public.curated_course_node_type, 'Merchandise financial planning', 'The point is to link buying decisions to sales, margin, inventory turns, open-to-buy, and markdown risk.', 1),
  ('55c0f02d-b5d3-48eb-98e4-e90ce8e3b1ec', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', 'f8feda35-8546-497f-b4fc-7a34d9d6c5ca', 'concept'::public.curated_course_node_type, 'Sales forecasting and inventory budgets', null, 0),
  ('dc8cfd14-a3de-4ce1-b8e8-98c2ef218a53', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', 'f8feda35-8546-497f-b4fc-7a34d9d6c5ca', 'concept'::public.curated_course_node_type, 'Open-to-buy planning', null, 1),
  ('b9944c9a-3e2f-41be-8e0a-6d8cde002349', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', 'f8feda35-8546-497f-b4fc-7a34d9d6c5ca', 'concept'::public.curated_course_node_type, 'Sell-through and weeks of supply', null, 2),
  ('dc09bb13-3769-4b40-b8c4-9072bd532100', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', '3171f12d-de13-427f-9034-3c3418ec1d58', 'subtopic'::public.curated_course_node_type, 'Category management', 'Students learn how retailer and supplier goals meet at category roles, shelf space, promotions, and shopper insight.', 2),
  ('10869826-9eef-40f6-8f1d-02b524c41fd6', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', 'dc09bb13-3769-4b40-b8c4-9072bd532100', 'concept'::public.curated_course_node_type, 'Category roles and scorecards', null, 0),
  ('452719ab-24f3-49d8-88c5-bb0c814188c6', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', 'dc09bb13-3769-4b40-b8c4-9072bd532100', 'concept'::public.curated_course_node_type, 'Planograms and space allocation', null, 1),
  ('4170a5ea-b1e9-438a-a21a-045f29a5868c', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', 'dc09bb13-3769-4b40-b8c4-9072bd532100', 'concept'::public.curated_course_node_type, 'Supplier collaboration and trade funds', null, 2),
  ('e1dc30e7-6c53-4f46-b8c7-407a4a04134d', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', null, 'topic'::public.curated_course_node_type, 'Buying, Vendor Relations, and Private Label', 'Retail buyers shape customer choice while managing suppliers, negotiations, ethics, and risk.', 6),
