  ('eec9ccd0-a85b-43cc-b7f1-f172176dbe6f', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', 'd1144ce4-b4da-43fe-85a6-a94c7fd8a357', 'concept'::public.curated_course_node_type, 'Reference prices and price image', null, 0),
