  ('1ab5429f-7ab6-446b-8935-84f7a1e4bdcc', 'b9c0d1e2-3f4a-4b79-8c60-7d8e9f0a1b29', 'd1144ce4-b4da-43fe-85a6-a94c7fd8a357', 'concept'::public.curated_course_node_type, 'Margin, elasticity, and willingness to pay', null, 2),
